{"content":"#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define NPAIRS 32
#define A_MASK 0x01010101u
#define B_MASK 0x00040000u

static inline uint32_t expand_key(uint32_t k) {
    return k ^ (k << 16) ^ (k * 12345u);
}
static inline uint8_t g_function(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t t = (uint8_t)(a + b + x);
    return (uint8_t)(((t << 2) | (t >> 6)) & 0xFF);
}
static inline uint32_t f_function(uint32_t v) {
    uint8_t x[4], y[4];
    for (int i = 0; i < 4; i++) { x[i] = v & 0xFF; v >>= 8; }
    y[2] = g_function(x[3]^x[2], x[1]^x[0], 1);
    y[3] = g_function(x[3], y[2], 0);
    y[1] = g_function(x[1]^x[0], y[2], 0);
    y[0] = g_function(x[0], y[1], 1);
    uint32_t o = 0;
    for (int i = 0; i < 4; i++) o |= ((uint32_t)y[i] << (8*i));
    return o;
}
static inline int par32(uint32_t v, uint32_t m) {
    return __builtin_popcount(v & m) & 1;
}

uint32_t L0[NPAIRS], R0[NPAIRS], L4[NPAIRS], R4[NPAIRS];
uint32_t L3t[NPAIRS], R3t[NPAIRS], L2t[NPAIRS], R2t[NPAIRS];

int main(void) {
    FILE *fp = fopen("/app/pairs.txt", "r");
    if (!fp) { perror("pairs.txt"); return 1; }
    for (int i = 0; i < NPAIRS; i++) {
        unsigned long long pt, ct;
        if (fscanf(fp, "%llu %llu", &pt, &ct) != 2) { fprintf(stderr, "parse fail line %d\n", i); return 1; }
        uint32_t PL = (pt >> 32) & 0xFFFFFFFF, PR = pt & 0xFFFFFFFF;
        uint32_t CL = (ct >> 32) & 0xFFFFFFFF, CR = ct & 0xFFFFFFFF;
        L0[i] = PL; R0[i] = PR ^ PL;
        R4[i] = CL; L4[i] = CR ^ CL;
    }
    fclose(fp);

    // Stage 1: recover K3 seed. V = par(L0,B)^par(R0,A)^par(L3,A)^par(R3,B) constant.
